function makeEmail(type,u) {
  const copy=emailCopy[u.language]||emailCopy.fr,loans=db.reservations.filter(r=>r.userId===u.id&&r.date.slice(0,7)===todayKey().slice(0,7)),items=loans.flatMap(r=>r.items),days=items.reduce((n,x)=>n+daysBetween(x.start,x.end),0);
  const subject=type==='newsletter'?copy.subject:copy.warning;
  return {id:crypto.randomUUID(),to:u.email,date:todayKey(),type,subject,html:localizeMarkup(`<div class="email-paper"><div class="email-brand">${logo()}</div><span class="email-eyebrow">${type==='newsletter'?'LA MANIVELLE · VOTRE BILAN':'LA MANIVELLE · VOTRE COMPTE'}</span><h2>${type==='newsletter'?copy.heading:esc(subject)}</h2><p>${copy.hello} ${esc(u.firstName)},</p>${type==='newsletter'?`<p>${copy.intro}</p><div class="email-stats"><div><strong>${items.length}</strong><span>${copy.loans}</span></div><div><strong>${days}</strong><span>${copy.days}</span></div></div><div class="email-carbon">${icon('leaf')}<strong>${items.length*5} ${copy.co2}</strong><p>${copy.footprint}</p></div>${!items.length?`<p>${copy.none}</p>`:''}<p>${copy.cta}</p>`:`<p>${copy.warningText}</p><p><strong>${fmt(addDays(todayKey(),30),true)}</strong></p><a class="button primary" href="#/connexion" data-action="email-reactivate">Conserver mon compte</a>`}<p class="email-signature">L’équipe La Manivelle<br>Emprunter plutôt qu’acheter.</p><small>Message de démonstration · ${type==='newsletter'?'Newsletter activée avec votre accord. Préférences disponibles dans Mon compte.':'Avertissement de service simulé. Aucune suppression sur le site réel.'}</small></div>`,u.language)};
}
function sendDemoEmail(type,account=user(),show=true) {
  if(!account) return toast('Connectez-vous pour essayer cette fonction.');
  if(type==='newsletter'&&!account.newsletter) return toast('Votre accord à la newsletter est nécessaire. Activez-le dans Mon compte.');
  const email=makeEmail(type,account);db.inbox.unshift(email);if(type==='warning')account.warningAt=todayKey();save();if(show)openModal('inbox',{emailId:email.id});
}
function deleteAccount(id) { const account=db.accounts.find(a=>a.id===id);db.accounts=db.accounts.filter(a=>a.id!==id);db.reservations=db.reservations.filter(r=>r.userId!==id);db.inbox=db.inbox.filter(e=>e.to!==account?.email);if(db.userId===id){db.userId=null;db.cart=[];}save(); }
function maintenance() { for(const account of [...db.accounts]) { const status=inactivityStatus(account);if(status==='warn')sendDemoEmail('warning',account,false);if(status==='delete')deleteAccount(account.id); } }
async function hashPassword(password,salt=crypto.randomUUID()) { const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:100000,hash:'SHA-256'},base,256);return {salt,hash:Array.from(new Uint8Array(bits)).map(n=>n.toString(16).padStart(2,'0')).join('')}; }
function signedIn(account) { db.userId=account.id;if(['fr','en'].includes(account.language))setLanguage(account.language);account.lastActive=todayKey();delete account.warningAt;save();const destination=sessionStorage.getItem('manivelle-return')||'/catalogue';sessionStorage.removeItem('manivelle-return');go(destination);toast(`Bienvenue ${account.firstName}. Votre sélection est conservée.`); }
function authNavigate(register) { if(!['/connexion','/inscription'].includes(route()))sessionStorage.setItem('manivelle-return',route());go(register?'/inscription':'/connexion'); }
function demoLogin(subscribed) { let account=db.accounts.find(a=>a.demo);if(!account){account={id:crypto.randomUUID(),demo:true,firstName:'Elena',lastName:'Martin',email:'elena.demo@example.com',language,newsletter:true,lastActive:todayKey()};db.accounts.push(account);}account.subscribed=subscribed;account.language=language;signedIn(account); }

document.addEventListener('click',e=>{
  if(e.target.closest('.skip-link')){e.preventDefault();document.querySelector('#main').focus();return;}
  const target=e.target.closest('[data-action]');
  if(!target){const link=e.target.closest('a[href^="#/"]');if(link){e.preventDefault();go(link.getAttribute('href').slice(1));return;}if(state.menu&&!e.target.closest('.dropdown')){state.menu=null;render();}return;}
  const action=target.dataset.action;
  if(action==='catalogue-page'){state.page=Number(target.dataset.page);refreshResults();document.querySelector('.results-toolbar')?.scrollIntoView({block:'start'});return;}
  if(target.disabled)return;
  if(action==='dev-menu'||action==='account-menu'){state.menu=state.menu===(action==='dev-menu'?'dev':'account')?null:action==='dev-menu'?'dev':'account';render();return;}
  if(action!=='preparation-help')document.querySelectorAll('.preparation-bar[aria-expanded="true"]').forEach(bar=>bar.setAttribute('aria-expanded','false'));
  if(action==='preparation-help'){target.setAttribute('aria-expanded',String(target.getAttribute('aria-expanded')!=='true'));return;}
  if(action==='object-requests')openModal('object-requests');
  if(action==='another-request'){state.requestSent=null;state.requestDrafts[requestKey()]='';refreshResults();document.querySelector('#object-request-message')?.focus();}
  if(action==='cart')go('/panier');
  if(action==='see-branches'){e.preventDefault();document.querySelector('#antennes')?.scrollIntoView({behavior:'smooth'});}
  if(action==='login')authNavigate(false);
  if(action==='register')authNavigate(true);
  if(action==='logout'||action==='demo-guest'){db.userId=null;save();state.menu=null;render();toast('Vous consultez le catalogue sans compte. Votre panier est conservé.');}
  if(action==='demo-user'||action==='demo-pass')demoLogin(action==='demo-pass');
  if(action==='banner-toggle'){db.banner=!db.banner;save();state.menu=null;render();}
  if(action==='date-filter'){state.draft={branch:state.branch,start:state.dates?.start||'',end:state.dates?.end||'',month:(state.dates?.start||todayKey()).slice(0,7)};state.error='';openModal('dates');}
  if(action==='clear-dates'){state.dates=null;render();}
  if(action==='clear-filters'){state.query='';state.page=1;state.branch='all';state.categories=[];state.stock=false;state.dates=null;render();}
  if(action==='close-modal')closeModal();
  if(action==='apply-dates'){const s=state.draft,error=validateRange(s.start,s.end,s.branch);if(error){state.error=error;renderModal();return;}state.dates={start:s.start,end:s.end};state.page=1;state.selections={};state.editing=null;closeModal();render();}
  if(action==='month'){const s=target.dataset.context==='filter'?state.draft:state.selections[target.dataset.context];const d=new Date(s.month+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+Number(target.dataset.direction));s.month=d.toISOString().slice(0,7);state.modal?renderModal():render();}
  if(action==='pick-date'){
    const context=target.dataset.context,s=context==='filter'?state.draft:state.selections[context],p=PRODUCTS.find(p=>String(p.id)===context),date=target.dataset.date;
    state.error='';if(!s.start||s.end||date<s.start){s.start=date;s.end='';}else{const error=validateRange(s.start,date,s.branch,{blocked:p?blockedDates(p,todayKey(),db.reservations):[]});if(error)state.error=error;else s.end=date;}state.modal?renderModal():render();
  }
  if(action==='add-cart'){
    const id=Number(target.dataset.id),p=PRODUCTS.find(x=>x.id===id),s=selection(p),error=validateRange(s.start,s.end,s.branch,{blocked:blockedDates(p,todayKey(),db.reservations)});if(error){state.error=error;render();return;}
    const entry={id,start:s.start,end:s.end,branch:s.branch,qty:1};
    if(state.editing!==null&&db.cart[state.editing]?.id===id){if(db.cart.some((x,i)=>i!==state.editing&&x.id===id&&s.start<=x.end&&s.end>=x.start)){toast('Cet objet figure déjà dans votre panier à ces dates.');return;}db.cart[state.editing]=entry;state.editing=null;save();go('/panier');toast('Les dates de cet objet ont été mises à jour.');return;}
    if(db.cart.some(x=>x.id===id&&s.start<=x.end&&s.end>=x.start)){toast('Cet objet figure déjà dans votre panier à ces dates.');return;}
    db.cart.push(entry);save();render();toast(`${p.name} a été ajouté au panier.`);
  }
  if(action==='remove-cart'){db.cart.splice(Number(target.dataset.index),1);save();render();}
  if(action==='edit-cart'){const i=Number(target.dataset.index),x=db.cart[i];state.selections[x.id]={...x,month:x.start.slice(0,7)};state.editing=i;go('/objet/'+x.id);}
  if(action==='checkout'){
    if(!user()){sessionStorage.setItem('manivelle-return','/panier');go('/connexion');return;}
    for(const [i,x]of db.cart.entries()){const p=PRODUCTS.find(p=>p.id===x.id),error=validateRange(x.start,x.end,x.branch,{blocked:blockedDates(p,todayKey(),db.reservations)});if(error){toast(`${p.name} : ${error}`);return;}if(db.cart.some((y,j)=>j<i&&y.id===x.id&&x.start<=y.end&&x.end>=y.start)){toast('Deux emprunts du même objet se chevauchent. Modifiez les dates.');return;}}
    if(!db.cart.length)return;
    const total=user().subscribed?0:db.cart.reduce((n,x)=>n+PRODUCTS.find(p=>p.id===x.id).price*x.qty,0),id=crypto.randomUUID();db.reservations.unshift({id,userId:user().id,reference:'LM-'+String(db.reservations.length+1).padStart(4,'0'),date:todayKey(),items:structuredClone(db.cart),total,remarks:sessionStorage.getItem('manivelle-remarks')||''});db.cart=[];user().lastActive=todayKey();save();sessionStorage.removeItem('manivelle-remarks');go('/confirmation/'+id);
  }
  if(action==='newsletter')sendDemoEmail('newsletter');
  if(action==='warning')sendDemoEmail('warning');
  if(action==='inbox')openModal('inbox');
  if(action==='select-email'){state.modal.emailId=target.dataset.id;renderModal();}
  if(action==='deactivate')openModal('deactivate');
  if(action==='confirm-deactivate'){deleteAccount(db.userId);closeModal();go('/catalogue');toast('Le compte de démonstration a été supprimé.');}
  if(action==='reset')openModal('reset');
  if(action==='confirm-reset'){db=empty();save();sessionStorage.removeItem('manivelle-return');sessionStorage.removeItem('manivelle-remarks');Object.assign(state,{query:'',branch:'all',categories:[],stock:false,dates:null,selections:{},editing:null,requestDrafts:{},requestSent:null});closeModal();go('/catalogue');toast('La démonstration est réinitialisée.');}
  if(action==='toggle-pass'){user().subscribed=!user().subscribed;save();render();toast('La formule de démonstration a été modifiée.');}
  if(action==='email-reactivate'){e.preventDefault();if(user()){user().lastActive=todayKey();delete user().warningAt;save();closeModal();go('/compte');toast('Votre activité est enregistrée. Votre compte est conservé.');}else{closeModal();authNavigate(false);}}
  if(action==='extend'){
    const r=db.reservations.find(r=>r.id===target.dataset.reservation&&r.userId===user()?.id),x=r?.items[Number(target.dataset.index)];if(!x||x.extended)return;const next=addDays(x.end,7),p=PRODUCTS.find(p=>p.id===x.id),other=db.reservations.flatMap(v=>v.items.filter(z=>z!==x&&z.id===x.id));if(other.some(z=>x.end<=z.end&&next>=z.start)||db.cart.some(z=>z.id===x.id&&x.end<=z.end&&next>=z.start)||!isOpen(next,x.branch)||blockedDates(p,todayKey()).some(b=>x.end<=b.end&&next>=b.start)){toast('La prolongation n’est pas disponible : l’objet est réservé sur cette période.');return;}x.end=next;x.extended=true;save();render();toast('Votre emprunt est prolongé de 7 jours, sans frais.');
  }
});
document.addEventListener('change',e=>{
  const el=e.target,what=el.dataset.change;
  if(what==='language'){switchLanguage(el.value);return;}
  if(['branch','stock','category','sort','per-page'].includes(what))state.page=1;
  if(what==='branch'){state.branch=el.value;state.selections={};state.editing=null;if(state.dates&&validateRange(state.dates.start,state.dates.end,state.branch)){state.dates=null;toast('Les dates ont été effacées : cette antenne est fermée un des jours choisis.');}render();}
  if(what==='stock'){state.stock=el.checked;refreshResults();}
  if(what==='category'){state.categories=el.checked?[...state.categories,el.value]:state.categories.filter(x=>x!==el.value);refreshResults();}
  if(what==='sort'||what==='view'||what==='per-page'){state[what==='per-page'?'perPage':what]=what==='per-page'?Number(el.value):el.value;refreshResults();}
  if(what==='item-branch'){const s=state.selections[el.dataset.id];s.branch=el.value;state.error='';if(s.start&&s.end&&validateRange(s.start,s.end,s.branch)){s.start='';s.end='';toast('Choisissez des dates pendant les jours d’ouverture de cette antenne.');}render();}
});
document.addEventListener('input',e=>{if(e.target.id==='catalogue-search'){state.query=e.target.value;state.page=1;refreshResults();}if(e.target.id==='object-request-message')state.requestDrafts[requestKey()]=e.target.value;if(e.target.id==='remarks')sessionStorage.setItem('manivelle-remarks',e.target.value);});
document.addEventListener('submit',async e=>{
  e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form));
  if(form.id==='search-form'){state.query=document.querySelector('#catalogue-search').value;refreshResults();return;}
  if(form.id==='object-request-form'){
    const message=String(values.message||'').trim();
    if(message.length<3){form.querySelector('.form-error').textContent=t('Décrivez l’objet souhaité en au moins 3 caractères.');return;}
    db.requests.unshift({id:crypto.randomUUID(),message:message.slice(0,600),query:state.query.trim(),branch:state.branch,date:todayKey()});
    try{save();}catch{db.requests.shift();form.querySelector('.form-error').textContent=t('Votre navigateur n’a pas pu enregistrer cette suggestion. Réessayez après avoir libéré de l’espace.');return;}
    state.requestSent={key:requestKey()};delete state.requestDrafts[requestKey()];refreshResults();return;
  }
  if(form.id==='preferences-form'){user().language=values.language;user().newsletter=!!values.newsletter;if(['fr','en'].includes(values.language))setLanguage(values.language);save();render();toast('Vos préférences ont été enregistrées.');return;}
  if(!['register-form','login-form'].includes(form.id))return;
  const button=form.querySelector('[type="submit"]');button.disabled=true;state.authError='';
  const fail=message=>{state.authError=message;form.querySelector('.form-error').textContent=t(message);button.disabled=false;};
  if(form.id==='register-form'){
    if(values.password!==values.confirm)return fail('Les mots de passe ne correspondent pas.');
    if(db.accounts.some(a=>a.email.toLowerCase()===values.email.trim().toLowerCase()))return fail('Un compte existe déjà avec cette adresse e-mail dans ce prototype.');
    const birth=values.birth,cutoff=`${Number(todayKey().slice(0,4))-18}${todayKey().slice(4)}`;if(!birth||birth>cutoff)return fail('Vous devez avoir au moins 18 ans pour créer un compte.');
    const password=await hashPassword(values.password),{password:discard,confirm,terms,newsletter,...profile}=values;
    const account={...profile,email:profile.email.trim(),id:crypto.randomUUID(),password,newsletter:!!newsletter,subscribed:false,lastActive:todayKey()};db.accounts.push(account);signedIn(account);
  }else{const account=db.accounts.find(a=>a.email.toLowerCase()===values.email.trim().toLowerCase());if(!account?.password)return fail('Adresse e-mail ou mot de passe incorrect. Vous pouvez utiliser un compte de démonstration ci-dessous.');const password=await hashPassword(values.password,account.password.salt);if(password.hash!==account.password.hash)return fail('Adresse e-mail ou mot de passe incorrect.');signedIn(account);}
});
window.addEventListener('hashchange',()=>{state.menu=null;state.error='';if(state.modal)closeModal();render();window.scrollTo({top:0});});
setLanguage(language);
maintenance();
if(user()){user().lastActive=todayKey();delete user().warningAt;save();}
render();
